insert into actividades (id, emoji, nombre, descripcion, foto, encuadre, orden) values
  ('senderismo', '🥾', '{"es":"Senderismo en Sierra Nevada","en":"Hiking in Sierra Nevada","fr":"Randonnée à Sierra Nevada","ca":"Senderisme a Sierra Nevada"}'::jsonb, '{"es":"Rutas guiadas para todos los niveles. Paisajes únicos, flora de alta montaña y vistas que no olvidarás.","en":"Guided hikes for all levels. Unique landscapes, high-mountain flora and views you''ll never forget.","fr":"Randonnées guidées pour tous les niveaux. Paysages uniques, flore de haute montagne et vues inoubliables.","ca":"Rutes guiades per a tots els nivells. Paisatges únics, flora d''alta muntanya i vistes que no oblidaràs."}'::jsonb, 'img/senderismo-sierra-nevada-rutas-alpujarra.png', 'arriba', 1),
  ('caballo', '🐴', '{"es":"Rutas a caballo","en":"Horse riding routes","fr":"Randonnées à cheval","ca":"Rutes a cavall"}'::jsonb, '{"es":"Los caminos históricos de La Alpujarra a lomos de caballo. Para principiantes y para quien ya monta.","en":"Historic trails of La Alpujarra on horseback. Suitable for beginners and experienced riders.","fr":"Les chemins historiques de La Alpujarra à cheval. Pour tous les niveaux.","ca":"Els camins històrics de La Alpujarra a cavall. Per a tots els nivells."}'::jsonb, 'img/ruta-caballo-alpujarra-sierra-nevada.jpg', 'centro', 2),
  ('4x4', '🚙', '{"es":"Excursiones en 4x4","en":"4x4 excursions","fr":"Excursions en 4x4","ca":"Excursions en 4x4"}'::jsonb, '{"es":"Accede a lugares que no están en ningún mapa. Pistas de montaña, cortijos y rincones secretos de Sierra Nevada.","en":"Access places not on any map. Mountain tracks, farmhouses and secret corners of Sierra Nevada.","fr":"Accédez à des endroits qui ne figurent sur aucune carte. Sierra Nevada en profondeur, sans limites.","ca":"Accedeix a llocs que no surten en cap mapa. Sierra Nevada a fons, sense límits."}'::jsonb, 'img/excursion-4x4-sierra-nevada-alpujarra.jpg', 'centro', 3)
